effect.shader:
vec3 samp(vec2 c){
return texture2DCv(inputImg.texture, clamp(c, 0.0005, 0.9995)).rgb;
}
vec3 prefilter(vec3 c){
float br = max(c.r, max(c.g, c.b));
float knee = threshold * softKnee + 1e-4;
float soft = br - threshold + knee;
soft = clamp(soft, 0.0, 2.0 * knee);
soft = soft * soft / (4.0 * knee);
float contrib = max(soft, br - threshold);
contrib /= max(br, 1e-4);
return c * contrib;
}
void main(){
vec2 res = acScreenSize;
float aspect = res.x / max(1.0, res.y);
vec2 uv = acScreenNorm;
vec4 src = texture2DCv(inputImg.texture, uv);
vec3 base = src.rgb;
float samples = 64.0;
if(quality == 0) samples = 24.0;
else if(quality == 1) samples = 48.0;
float k = mix(7.0, 1.2, scatter);
float golden = 2.39996323;
vec3 sum = vec3(0.0);
float wsum = 0.0;
for(int i = 0; i < 64; i++){
if(float(i) >= samples) break;
float fi = float(i);
float t = (fi + 0.5) / samples;
float r = sqrt(t);
float ang = fi * golden;
vec2 off = vec2(cos(ang), sin(ang)) * r * radius;
off.x /= aspect;
float w = exp(-r * r * k);
sum += prefilter(samp(uv + off)) * w;
wsum += w;
}
vec3 glow = sum / max(wsum, 1e-4);
glow *= intensity * glowColor.rgb;
vec3 outc;
if(blendMode == 0)      outc = base + glow;
else if(blendMode == 1) outc = 1.0 - (1.0 - base) * (1.0 - clamp(glow, 0.0, 1.0));
else                    outc = max(base, glow);
if(glowOnly) outc = glow;
outc = mix(base, outc, mixAmt);
gl_FragColor = vec4(outc, src.a);
}
